begin;

with guide_data as (
  select *
  from jsonb_to_recordset($guides$
[{"slug":"barbell-back-squat","start":"Stand under the bar with it supported across the upper back, hands secure, feet about shoulder width and the trunk braced.","finish":"Reach the deepest controlled squat that keeps the heels planted, knees tracking with the toes and the torso stable.","setup":["Set the rack hooks just below shoulder height and place the safety arms slightly below your planned bottom position.","Center the bar across the upper traps or rear shoulders, then grip it evenly and pull the elbows into a stable position.","Unrack with both feet, take one or two small steps back and establish a balanced stance before beginning."],"execution":["Inhale and brace the abdomen, then bend the knees and hips together while keeping pressure through the full foot.","Descend under control until your available depth is reached without the pelvis tucking excessively or the heels lifting.","Drive the floor away, keep the knees aligned over the toes and stand tall without throwing the hips forward."],"cues":["Keep the bar stacked over the middle of the foot.","Spread the floor with your feet and keep the knees following the toes.","Maintain ribcage-over-pelvis control from the unrack through the lockout."],"mistakes":["Allowing the knees to collapse inward during the descent or ascent.","Losing the brace and folding the torso forward out of the bottom.","Descending deeper than mobility allows and letting the heels or arches lose contact."],"safety":["Use safety arms or an experienced spotter whenever the load could prevent a controlled rerack.","Stop the set if pain, dizziness or loss of bar control occurs; reduce load or range before continuing."],"breathing":"Take a full breath and brace before each descent; keep the brace through the hardest part of the ascent and exhale near the top.","tempo":"Use about 2–3 seconds down, a brief controlled transition at the bottom and a strong but smooth ascent.","muscles":["Quadriceps","Gluteus maximus","Hamstrings","Core","Spinal erectors"]},{"slug":"conventional-deadlift","start":"Stand with the bar over the middle of the feet, shins close, hips hinged, spine neutral and both hands gripping the bar securely.","finish":"Stand tall with the hips and knees extended, the bar resting against the thighs and the ribs stacked over the pelvis.","setup":["Use flat, stable footwear and position the bar roughly over the shoelaces at mid-foot.","Hinge down, take a secure grip just outside the legs and bring the shins gently toward the bar.","Lift the chest enough to create a neutral trunk, engage the lats and remove slack from the bar before it leaves the floor."],"execution":["Brace the trunk and push the floor away so the hips and shoulders rise together.","Keep the bar close to the legs as it passes the knees and continue extending the hips.","Finish tall without leaning backward, then hinge the hips and bend the knees to return the bar under control."],"cues":["Squeeze the armpits toward the body to keep the bar close.","Push the ground away instead of jerking the bar upward.","Keep the chest and hips rising at the same rate from the floor."],"mistakes":["Rounding the lower back or losing tension before the bar moves.","Starting with the bar too far from the body and letting it drift forward.","Hyperextending the lower back or shrugging at the top."],"safety":["Use a load that allows every repetition to start from a stable braced position; reset between repetitions when needed.","Stop if sharp back pain, numbness or loss of grip control occurs, and avoid mixed grip overuse when it irritates the shoulder or biceps."],"breathing":"Inhale and brace before lifting; hold the brace through the floor-to-knee portion and exhale after reaching a stable lockout.","tempo":"Create tension for 1–2 seconds before the pull, lift smoothly, then lower in roughly 2 seconds while keeping the bar close.","muscles":["Gluteus maximus","Hamstrings","Quadriceps","Spinal erectors","Latissimus dorsi","Core"]},{"slug":"barbell-bench-press","start":"Lie with eyes under the bar, feet planted, shoulder blades set on the bench and the bar held above the chest with straight wrists.","finish":"Lower the bar under control to the mid-to-lower chest with forearms close to vertical and the upper back still firmly supported.","setup":["Set the rack so the bar can be unracked without losing shoulder position and place safety arms just below chest level when available.","Plant the feet, create a stable upper-back arch and draw the shoulder blades down and together.","Grip the bar evenly, keep the wrists stacked over the forearms and unrack to a position above the shoulders."],"execution":["Inhale and maintain full-body tension as the bar travels down toward the mid-to-lower chest.","Touch lightly without bouncing while keeping the elbows at a comfortable angle below the shoulders.","Press the bar upward and slightly back toward the rack while driving through the feet and keeping the upper back anchored."],"cues":["Keep the forearms vertical when the bar reaches the chest.","Bend the bar apart to create shoulder and upper-back tension.","Press from a stable base: feet, glutes and shoulder blades stay connected."],"mistakes":["Bouncing the bar off the chest or losing control near the bottom.","Letting the wrists fold backward or the elbows flare directly sideways.","Lifting the hips off the bench to finish a repetition."],"safety":["Use a spotter or correctly positioned safety arms for challenging sets, and use collars when appropriate for the setup.","Do not force a painful shoulder range; adjust grip width, touch point or load if discomfort appears."],"breathing":"Inhale and brace before lowering; keep tension through the press and exhale as the bar passes the sticking point or reaches lockout.","tempo":"Lower in 2–3 seconds, touch with control and press smoothly without a bounce.","muscles":["Pectoralis major","Triceps","Anterior deltoids","Upper back"]},{"slug":"overhead-press","start":"Stand tall with the bar or dumbbells at shoulder height, forearms vertical, glutes engaged and the abdomen braced.","finish":"Press the weight overhead until the arms are extended and the load is stacked over the middle of the body without lower-back overextension.","setup":["Choose a stance about hip width and hold the load with wrists stacked over the forearms.","Brace the abdomen, squeeze the glutes and keep the ribs positioned over the pelvis.","Create a clear path by drawing the chin slightly back without extending the neck."],"execution":["Press upward close to the face while keeping the trunk still and the elbows moving under the load.","As the weight clears the forehead, bring the head gently through so the arms finish beside the ears.","Lower the weight under control to the shoulders while maintaining the same braced posture."],"cues":["Finish with the weight over the middle of the foot, not in front of the body.","Keep the ribs down and glutes tight throughout the repetition.","Move the head around the weight instead of moving the weight in a large forward arc."],"mistakes":["Leaning backward and turning the movement into an incline press.","Pressing the load forward and failing to stack it over the shoulders.","Losing wrist alignment or allowing the elbows to drift too far behind the bar."],"safety":["Use a load that can be lowered safely and avoid pressing behind the neck.","Reduce range or use a neutral-grip dumbbell variation if overhead positioning causes shoulder pain."],"breathing":"Inhale and brace before the press; exhale after the weight clears the most difficult point, then inhale again before lowering.","tempo":"Press in 1–2 seconds, stabilize briefly overhead and lower in about 2 seconds.","muscles":["Anterior deltoids","Medial deltoids","Triceps","Upper chest","Core"]},{"slug":"rear-delt-fly","start":"Hinge forward or use a supported machine position with the chest stable, arms reaching down or forward and elbows softly bent.","finish":"Move the arms out and slightly back until they align with the shoulders while the torso and neck remain still.","setup":["Use light resistance and choose either a chest-supported bench, hinged dumbbell position or reverse pec-deck setup.","Set the shoulders away from the ears and maintain a small fixed bend in the elbows.","Brace the torso so the movement comes from the shoulders rather than body momentum."],"execution":["Sweep the arms outward in a wide arc while keeping the hands and elbows on the same general plane.","Pause briefly when the rear shoulders and upper back are contracted.","Return slowly until the arms reach the starting position without letting the weight pull the shoulders forward abruptly."],"cues":["Lead with the elbows rather than the hands.","Keep the neck long and shoulders down.","Use a range that keeps tension in the rear delts instead of forcing the arms far behind the torso."],"mistakes":["Swinging the torso or using excessive weight.","Shrugging the shoulders upward during the lift.","Turning the movement into a row by bending the elbows more as the arms move back."],"safety":["Avoid forcing the shoulders into an extreme backward position, especially if there is a history of shoulder irritation.","Use chest support if maintaining a stable hip hinge causes lower-back fatigue."],"breathing":"Exhale as the arms open and inhale during the controlled return.","tempo":"Raise in about 2 seconds, pause briefly, then lower in 2–3 seconds.","muscles":["Posterior deltoids","Rhomboids","Middle trapezius","Rotator cuff"]},{"slug":"pull-up","start":"Hang from the bar with a secure grip, arms extended, legs controlled and shoulders active rather than completely shrugged.","finish":"Pull until the upper chest approaches the bar and the elbows move down beside the torso without craning the neck.","setup":["Choose a grip width that allows pain-free shoulder motion and wrap the thumbs securely around the bar.","Start from a controlled hang with the ribs down, glutes lightly engaged and minimal swinging.","Set the shoulders by drawing them slightly down before bending the elbows."],"execution":["Drive the elbows down and back as the chest rises toward the bar.","Keep the trunk controlled and avoid kicking or excessive arching.","Lower in a smooth controlled path until the elbows are extended and the shoulders return to an active hang."],"cues":["Think chest to bar and elbows toward the ribs.","Keep the body quiet and initiate with the shoulder blades.","Use assistance or a band before sacrificing range and control."],"mistakes":["Kipping or swinging during a strict repetition.","Shrugging at the bottom and pulling only with the arms.","Craning the neck to get the chin over the bar."],"safety":["Use an assisted machine, band or lower bar if grip or shoulder control is not sufficient for a full bodyweight repetition.","Stop if shoulder, elbow or hand pain increases, and step down safely rather than dropping from height."],"breathing":"Exhale during the upward pull and inhale through the controlled lowering phase.","tempo":"Pull in 1–2 seconds, pause briefly near the top and lower for 2–3 seconds.","muscles":["Latissimus dorsi","Biceps","Rhomboids","Lower trapezius","Core","Forearms"]},{"slug":"barbell-bent-over-row","start":"Hold the bar with arms extended, hips hinged, knees softly bent and the torso fixed at a stable forward angle.","finish":"Pull the bar toward the lower ribs or upper abdomen with elbows moving behind the torso while the spine and hip position remain unchanged.","setup":["Grip the bar slightly wider than shoulder width and stand with the feet about hip width.","Hinge the hips until the torso reaches a sustainable angle, then brace the abdomen and keep the neck neutral.","Let the arms extend fully while maintaining lat and upper-back tension."],"execution":["Pull the bar toward the lower ribs by driving the elbows back and keeping the bar close.","Pause briefly without lifting the torso to meet the bar.","Lower the bar under control until the elbows are straight while preserving the same hinge and brace."],"cues":["Freeze the torso and move the bar with the back and arms.","Row toward the lower ribs, not the shoulders.","Keep pressure balanced through the feet and the bar close to the legs."],"mistakes":["Standing more upright as the bar rises.","Rounding the lower back or losing the hip hinge.","Using a load that requires bouncing or jerking from the floor."],"safety":["Choose a torso angle and load that can be held without lower-back pain or repeated loss of position.","Use a chest-supported row variation if trunk fatigue limits back training quality."],"breathing":"Inhale and brace before the pull; exhale near the top while maintaining trunk tension, then inhale during the return.","tempo":"Pull in 1–2 seconds, pause briefly at the torso and lower in 2–3 seconds.","muscles":["Latissimus dorsi","Rhomboids","Middle trapezius","Posterior deltoids","Biceps","Spinal erectors"]},{"slug":"back-extension","start":"Set the hip pad below the front of the pelvis, anchor the feet and hinge forward with a neutral spine and arms secured.","finish":"Extend the hips until the body forms a straight line from head to heels without arching beyond neutral.","setup":["Adjust the bench so the hips can move freely while the thighs and ankles remain supported.","Cross the arms over the chest or hold a light load close to the body.","Brace the abdomen and keep the neck aligned with the spine before beginning."],"execution":["Hinge forward through the hips while keeping the back long and controlled.","Descend only as far as hamstring flexibility and trunk control allow.","Squeeze the glutes and hamstrings to return until the body reaches a straight line."],"cues":["Move at the hips rather than repeatedly bending through the lower back.","Stop at neutral instead of leaning backward at the top.","Keep the load close to the chest when adding resistance."],"mistakes":["Hyperextending the lumbar spine at the top.","Dropping quickly into the bottom position.","Setting the pad too high so the hips cannot hinge freely."],"safety":["Begin with bodyweight and a comfortable range; add load only after the hip hinge remains consistent.","Stop if the movement produces sharp back pain or radiating symptoms."],"breathing":"Inhale during the descent and exhale while extending the hips back to neutral.","tempo":"Lower in 2–3 seconds, pause briefly in the stretched position and rise in about 2 seconds.","muscles":["Gluteus maximus","Hamstrings","Spinal erectors"]},{"slug":"forearm-plank","start":"Place the elbows directly under the shoulders, extend the legs and support the body on the forearms and toes.","finish":"Maintain one straight line from head through heels for the planned hold without the hips sagging, rising or rotating.","setup":["Place the forearms parallel or clasp the hands without letting the elbows drift wider than the shoulders.","Step the feet back, squeeze the glutes and draw the ribs toward the pelvis.","Push the forearms into the floor so the upper back stays active and the neck remains neutral."],"execution":["Maintain steady abdominal tension while breathing normally.","Keep equal pressure through both forearms and both feet.","End the hold as soon as the spine, shoulder position or breathing can no longer remain controlled."],"cues":["Imagine pulling the elbows toward the toes without actually moving.","Squeeze the glutes and keep the belt line level.","Keep breathing behind the brace instead of holding the breath."],"mistakes":["Allowing the hips to sag and increasing lower-back extension.","Raising the hips too high to avoid abdominal effort.","Shrugging into the shoulders or letting the head drop."],"safety":["Use a shorter hold or elevate the forearms if shoulder or lower-back position cannot be maintained.","Stop if numbness, sharp shoulder pain or low-back pain develops."],"breathing":"Use slow nasal or controlled diaphragmatic breaths while maintaining moderate abdominal pressure.","tempo":"This is an isometric hold; prioritize perfect position for 10–60 seconds rather than extending the duration after form changes.","muscles":["Rectus abdominis","Transverse abdominis","Obliques","Gluteus maximus","Shoulders"]},{"slug":"hanging-knee-raise","start":"Hang from the bar with arms extended, grip secure, shoulders active and legs together beneath the body.","finish":"Raise the knees toward the torso while curling the pelvis slightly upward and keeping the body from swinging.","setup":["Choose a bar height that allows a safe mount and dismount, and use a secure full grip.","Begin in an active hang with the shoulders gently drawn down and the ribs controlled.","Bring the legs together and reduce momentum before the first repetition."],"execution":["Exhale and lift the knees by flexing the hips and drawing the pelvis toward the ribs.","Pause briefly without swinging or throwing the head backward.","Lower the legs slowly until the body returns to a quiet active hang."],"cues":["Curl the pelvis instead of only lifting the thighs.","Keep the shoulders active and the body quiet.","Use a smaller range if the lower back arches or swinging begins."],"mistakes":["Using a large forward-and-back swing to raise the knees.","Relaxing completely through the shoulders at the bottom.","Dropping the legs quickly and losing abdominal control."],"safety":["Use captain-chair support or straps only when appropriate if grip is the limiting factor, but maintain safe shoulder positioning.","Step down carefully and stop if shoulder, elbow or lower-back pain appears."],"breathing":"Exhale as the knees rise and inhale during the controlled lowering phase.","tempo":"Raise in 1–2 seconds, pause briefly and lower in 2–3 seconds.","muscles":["Rectus abdominis","Hip flexors","Obliques","Forearms","Latissimus dorsi"]},{"slug":"incline-treadmill-walk","start":"Stand centered on the moving belt with a tall posture, relaxed shoulders and a speed and incline that allow a natural stride.","finish":"Continue walking with even steps, controlled breathing and the trunk upright without relying on the handrails.","setup":["Attach the safety clip when available and begin at a low speed before adding incline.","Choose footwear with secure traction and position yourself far enough from the console for a normal stride.","Increase either speed or incline gradually rather than changing both aggressively at once."],"execution":["Land each step quietly under the body and roll through the foot into the next stride.","Keep the torso tall with a slight natural forward lean from the ankles when the incline increases.","Adjust intensity so posture and breathing remain appropriate for the planned training zone."],"cues":["Use the rails only briefly for balance or setup, not to unload bodyweight.","Keep the stride compact and rhythmic as incline rises.","Let the arms swing naturally and keep the shoulders relaxed."],"mistakes":["Holding the rails continuously while using an incline or speed that is too high.","Overstriding and landing heavily in front of the body.","Looking down for long periods and rounding the upper back."],"safety":["Start and stop at low speed, use the emergency clip and step onto the side rails only after slowing the belt.","Reduce intensity immediately for chest pain, dizziness, unusual shortness of breath or loss of balance."],"breathing":"Use steady rhythmic breathing; during moderate work, aim to maintain a pace that still allows short sentences.","tempo":"Maintain a smooth continuous cadence; change incline or speed in small steps every 30–60 seconds when progressing.","muscles":["Gluteus maximus","Quadriceps","Hamstrings","Calves","Cardiorespiratory system"]},{"slug":"stationary-bike","start":"Sit with the hips centered on the saddle, hands relaxed on the bars and one knee slightly bent when its pedal is at the bottom.","finish":"Pedal through a complete smooth cycle with stable hips, knees tracking forward and resistance appropriate for the target effort.","setup":["Adjust saddle height so the knee remains slightly bent at the bottom of the pedal stroke.","Set the saddle fore-aft position so the knees track comfortably and the hips do not rock.","Secure the feet in the pedals and begin with low resistance before increasing intensity."],"execution":["Push and pull through smooth circles rather than stomping only on the downward phase.","Keep the knees aligned over the feet and the upper body relaxed.","Increase resistance or cadence gradually while maintaining a stable pelvis and controlled breathing."],"cues":["Keep the hips quiet on the saddle.","Use light hands and relaxed shoulders.","Choose resistance that makes the pedal stroke controlled instead of choppy."],"mistakes":["Setting the saddle so low that the knees stay deeply bent at the bottom.","Rocking the hips side to side to reach the pedals.","Using very low resistance at excessive cadence and losing pedal control."],"safety":["Stop pedaling before dismounting and ensure adjustment knobs are locked before starting.","Reduce intensity for knee pain, numbness, dizziness, chest pain or unusual shortness of breath."],"breathing":"Use steady rhythmic breathing matched to cadence; avoid breath-holding during hard resistance intervals.","tempo":"For steady work, maintain a consistent comfortable cadence; for intervals, change resistance or cadence gradually and recover fully between efforts.","muscles":["Quadriceps","Gluteus maximus","Hamstrings","Calves","Cardiorespiratory system"]}]
$guides$::jsonb) as guide(
    slug text,
    start text,
    finish text,
    setup text[],
    execution text[],
    cues text[],
    mistakes text[],
    safety text[],
    breathing text,
    tempo text,
    muscles jsonb
  )
)
insert into public.exercise_technique_guides (
  exercise_id,
  start_position,
  finish_position,
  setup_steps,
  execution_steps,
  coaching_cues,
  common_mistakes,
  safety_notes,
  breathing,
  tempo_guidance,
  muscle_highlights,
  content_source,
  status,
  version,
  is_active
)
select
  exercise.id,
  guide.start,
  guide.finish,
  guide.setup,
  guide.execution,
  guide.cues,
  guide.mistakes,
  guide.safety,
  guide.breathing,
  guide.tempo,
  guide.muscles,
  'editorial',
  'published',
  1,
  true
from guide_data guide
join public.exercise_library exercise
  on exercise.slug = guide.slug
where exercise.is_active
on conflict (exercise_id) do update
set
  start_position = excluded.start_position,
  finish_position = excluded.finish_position,
  setup_steps = excluded.setup_steps,
  execution_steps = excluded.execution_steps,
  coaching_cues = excluded.coaching_cues,
  common_mistakes = excluded.common_mistakes,
  safety_notes = excluded.safety_notes,
  breathing = excluded.breathing,
  tempo_guidance = excluded.tempo_guidance,
  muscle_highlights = excluded.muscle_highlights,
  content_source = excluded.content_source,
  status = excluded.status,
  version = public.exercise_technique_guides.version + 1,
  is_active = true,
  updated_at = now();

do $validation$
declare
  completed_guides integer;
  uncovered_exercises integer;
begin
  select count(*)
  into completed_guides
  from public.exercise_technique_guides guide
  join public.exercise_library exercise on exercise.id = guide.exercise_id
  where exercise.slug = any(array['barbell-back-squat','conventional-deadlift','barbell-bench-press','overhead-press','rear-delt-fly','pull-up','barbell-bent-over-row','back-extension','forearm-plank','hanging-knee-raise','incline-treadmill-walk','stationary-bike']::text[])
    and exercise.is_active
    and guide.is_active
    and guide.status = 'published'
    and nullif(btrim(guide.start_position), '') is not null
    and nullif(btrim(guide.finish_position), '') is not null
    and cardinality(guide.setup_steps) >= 3
    and cardinality(guide.execution_steps) >= 3
    and cardinality(guide.coaching_cues) >= 3
    and cardinality(guide.common_mistakes) >= 3
    and cardinality(guide.safety_notes) >= 2
    and nullif(btrim(guide.breathing), '') is not null
    and nullif(btrim(guide.tempo_guidance), '') is not null
    and jsonb_array_length(guide.muscle_highlights) >= 3;

  if completed_guides <> 12 then
    raise exception 'Expected 12 complete technique guides, found %', completed_guides;
  end if;

  select count(*)
  into uncovered_exercises
  from public.exercise_library exercise
  left join public.exercise_technique_guides guide
    on guide.exercise_id = exercise.id
   and guide.is_active
   and guide.status = 'published'
  where exercise.is_active
    and guide.exercise_id is null;

  if uncovered_exercises <> 0 then
    raise exception 'Active exercise library still has % exercises without published technique guides', uncovered_exercises;
  end if;
end
$validation$;

commit;
